// ─── Configurable Variables ───────────────────────────────────────────────
// Edit these four values to customise the workflow without touching other nodes.
const GITHUB_OWNER  = 'octocat';          // GitHub org or user (e.g. 'vercel')
const GITHUB_REPO   = 'Hello-World';      // Repository name  (e.g. 'next.js')
const LANGUAGE      = 'EN';              // 'EN' for English, 'FR' for French
const DISCORD_URL   = 'https://discord.com/api/webhooks/YOUR_WEBHOOK_ID/YOUR_WEBHOOK_TOKEN';
// ──────────────────────────────────────────────────────────────────────────

// Build the ISO-8601 timestamp for exactly 7 days ago (start of window)
const since = new Date();
since.setDate(since.getDate() - 7);
const sinceISO = since.toISOString();

return [{
  json: {
    github_owner:   GITHUB_OWNER,
    github_repo:    GITHUB_REPO,
    language:       LANGUAGE,
    discord_url:    DISCORD_URL,
    since:          sinceISO
  }
}];

// Retrieve outputs from parallel GitHub fetches
const config   = $('Config Variables').item.json;
const since    = new Date(config.since);

// --- Commits ---
const commitsRaw = $('Fetch Commits').all();
const commits = commitsRaw
  .filter(item => item.json && item.json.sha)
  .map(item => ({
    sha:     item.json.sha.substring(0, 7),
    message: (item.json.commit?.message || '').split('\n')[0].substring(0, 120),
    author:  item.json.commit?.author?.name || 'unknown',
    date:    item.json.commit?.author?.date || ''
  }));

// --- Closed Issues (exclude PRs) ---
const issuesRaw = $('Fetch Closed Issues').all();
const issues = issuesRaw
  .filter(item => item.json && item.json.id && !item.json.pull_request)
  .filter(item => {
    const closed = new Date(item.json.closed_at);
    return closed >= since;
  })
  .map(item => ({
    number: item.json.number,
    title:  (item.json.title || '').substring(0, 120),
    labels: (item.json.labels || []).map(l => l.name).join(', ')
  }));

// --- Merged PRs ---
const prsRaw = $('Fetch Merged PRs').all();
const prs = prsRaw
  .filter(item => item.json && item.json.merged_at)
  .filter(item => {
    const merged = new Date(item.json.merged_at);
    return merged >= since;
  })
  .map(item => ({
    number: item.json.number,
    title:  (item.json.title || '').substring(0, 120),
    author: item.json.user?.login || 'unknown',
    merged: item.json.merged_at
  }));

const weekStart = since.toISOString().split('T')[0];
const weekEnd   = new Date().toISOString().split('T')[0];

return [{
  json: {
    ...config,
    week_start:    weekStart,
    week_end:      weekEnd,
    commit_count:  commits.length,
    issue_count:   issues.length,
    pr_count:      prs.length,
    commits_text:  commits.map(c => `- [${c.sha}] ${c.message} (${c.author})`).join('\n') || 'None',
    issues_text:   issues.map(i => `- #${i.number}: ${i.title}${i.labels ? ' ['+i.labels+']' : ''}`).join('\n') || 'None',
    prs_text:      prs.map(p => `- #${p.number}: ${p.title} (by @${p.author})`).join('\n') || 'None'
  }
}];

const d = $input.item.json;

const langInstruction = d.language === 'FR'
  ? 'Reponds entierement en francais.'
  : 'Respond entirely in English.';

const systemPrompt = `You are an engineering team lead who writes concise, insightful weekly activity reports for developer teams. ${langInstruction}

Guidelines:
- Write in a friendly but professional narrative style.
- Group insights naturally: highlight the most significant merged PRs, notable commits, and resolved issues.
- If any category has zero items, mention it briefly (e.g. "No issues were closed this week.").
- Include a brief sentiment/momentum note at the end.
- Format the report with clear markdown sections: ## Summary, ## Merged Pull Requests, ## Closed Issues, ## Commits, ## Momentum.
- Keep the whole report under 1800 characters so it fits in a Discord message.`;

const userPrompt = `Repository: ${d.github_owner}/${d.github_repo}\nPeriod: ${d.week_start} -> ${d.week_end}\n\n### Commits (${d.commit_count})\n${d.commits_text}\n\n### Closed Issues (${d.issue_count})\n${d.issues_text}\n\n### Merged Pull Requests (${d.pr_count})\n${d.prs_text}\n\nPlease write the weekly narrative report now.`;

return [{
  json: {
    ...d,
    system_prompt: systemPrompt,
    user_prompt:   userPrompt
  }
}];

const claudeResponse = $input.item.json;
const config         = $('Aggregate GitHub Data').item.json;

let summary = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  const textBlock = claudeResponse.content.find(b => b.type === 'text');
  summary = textBlock ? textBlock.text : 'No summary generated.';
} else {
  summary = 'Error: unexpected response from Claude API.';
}

if (summary.length > 1950) {
  summary = summary.substring(0, 1947) + '...';
}

return [{
  json: {
    discord_url: config.discord_url,
    summary,
    repo:        `${config.github_owner}/${config.github_repo}`,
    week_start:  config.week_start,
    week_end:    config.week_end
  }
}];

const d = $('Extract Summary').item.json;
console.log(`[GitHub Weekly Summary] Report delivered for ${d.repo} | ${d.week_start} -> ${d.week_end}`);
return [{
  json: {
    status: 'success',
    repo:   d.repo,
    period: `${d.week_start} -> ${d.week_end}`,
    chars:  d.summary.length
  }
}];
